'use strict';
const STORAGE='answority-dashboard-v1';
const fresh=()=>({schema:1,accessApproved:false,blocked:false,probePending:false,training:'Limit',answerReaders:'Allow',resolved:[],guided:[],hours:'7 am–7 pm, Monday–Friday',factVersion:1,pricing:'proposed',interview:'',diagnosis:'',diagnosisReason:'',published:[],drafts:{},approvals:{},paused:false,connections:{'WordPress plugin':true,'Search Console':true,'Google Business Profile':true,'Bing Places':false,HubSpot:true,LinkedIn:false},leads:['Qualified','Qualified','Pending','Unqualified'],panel:1,bookmarked:[],events:[],auditRun:false});
let state=fresh();try{const data=JSON.parse(localStorage.getItem(STORAGE));if(data?.schema===1)state={...fresh(),...data}}catch{}
let tab='visible',answerFilter='All engines',questionFilter='All intents',visitorPeriod='90',toastTimer;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(text,kind='')=>`<span class="tag ${kind}">${esc(text)}</span>`;
const btn=(label,action,id='',style='')=>`<button class="button ${style}" data-action="${action}" data-id="${id}">${label}</button>`;
const go=(label,route,style='')=>`<a class="button ${style}" href="#${route}">${label}</a>`;
const heading=(category,title,sub,action='')=>`<div class="heading"><div><p class="eyebrow">${category}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="row">${action}</div></div>`;
const card=(title,body,extra='')=>`<section class="card ${extra}"><div class="section-head"><h2>${title}</h2></div>${body}</section>`;
const table=(heads,rows,cls='')=>`<div class="table-wrap"><table class="${cls}"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
const metric=(label,value,note,foot,icon='↗')=>`<section class="card"><div class="metric-label">${label}<span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="change">${note}</div><div class="metric-foot">${foot}</div></section>`;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{toast('Storage unavailable. Changes last for this visit only.')}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal()}
function log(title){state.events.unshift({title,detail:'Simulated just now'});save()}
const isResolved=id=>state.resolved.includes(id);
function accessCount(){return state.blocked||state.probePending?4:5}
const drifts=[{id:'phone',surface:'Bing Places',severity:'Critical',field:'Phone number',old:'+1 (303) 555-0114',correct:'+1 (303) 555-0142',mechanism:'Guided fix',detail:'ChatGPT repeats this old phone number in the sampled answer. Bing Places is the likely source; causation is unconfirmed.'},{id:'hours',surface:'Google Business Profile',severity:'Medium',field:'Support hours',old:'24 hours, every day',correct:()=>state.hours,mechanism:'Approval + simulated write',detail:'The profile says 24 hours. Standard support hours and after-hours P1 cover must be described separately.'},{id:'service',surface:'Clutch',severity:'Low',field:'Service area',old:'Denver only',correct:'Denver–Boulder metro',mechanism:'Guided fix',detail:'The profile omits Boulder from the approved coverage area.'}];
const plans=[{id:'managed',title:'Make your managed IT answer more specific',path:'/managed-it-services',score:92,type:'Page refresh',reason:'AI-surface impressions rose 3.1× while clicks fell 24%. Add approved specifics to the existing answer.',old:'We provide around-the-clock IT support and complete security solutions for businesses of all sizes. Contact Northstar IT for a quote.',text:()=>`Managed IT services in Denver and Boulder\n\nNorthstar IT provides managed and co-managed IT support for businesses in the Denver–Boulder metro area. Standard support hours are ${state.hours}.\n\nFor P1 incidents, covered clients can reach the after-hours line under their service agreement. P2 coverage must be confirmed separately; we do not promise around-the-clock cover for every ticket.\n\nTalk to our team about your environment and support requirements. Call +1 (303) 555-0142 to arrange a discovery conversation.`},{id:'pricing',title:'Publish your approved pricing band',path:'/pricing',score:86,type:'Fact refresh',reason:'Pricing is the most-read page in the example reader log. Buyers need scope, minimums and a clear next step.',old:'Contact us for pricing tailored to your business.',text:()=>`Managed IT pricing\n\nOur illustrative managed IT band is $125–$185 per user per month, subject to scope, with a 25-user minimum. Onboarding is quoted separately. A 12-month initial term applies.\n\nNorthstar IT serves the Denver–Boulder metro area. Standard support hours are ${state.hours}.\n\nAsk for a scoped proposal by calling +1 (303) 555-0142.`},{id:'switch',title:'Answer the questions buyers ask before switching',path:'/switching-it-provider',score:79,type:'New page',reason:'Northstar is absent on three of four sampled engines for switching questions.',old:'No page exists yet. A new page always requires review.',text:()=>`Switching your IT provider in Denver\n\nNorthstar IT supports businesses across the Denver–Boulder metro area. We begin with a discovery conversation to understand your current environment, service needs and transition constraints.\n\nStandard support hours are ${state.hours}. Ask us to agree on a transition plan before any access changes.\n\nCall +1 (303) 555-0142 to discuss your next step. A migration timetable is agreed after review, not guaranteed in advance.`}];
function navData(){return [['WORKSPACE'],['overview','◫','Overview'],['diagnosis','⌁','Diagnosis'],['answers','◎','Answer accuracy'],['questions','◇','Buyer questions'],['plan','↗','Monthly plan'],['FACTS & ACCESS'],['facts','▤','Company facts'],['sync','⇄','Surface sync'],['fact-pages','▧','Fact pages'],['access','⊞','AI access'],['PROOF & SETUP'],['visitors','◷','AI visitor report'],['enquiries','♧','Enquiry capture'],['results','▥','Owner report'],['connections','⊕','Connections'],['audit','⌕','Free answer audit'],['controls','⚙','Controls']]}
function trend(){return `<svg class="chart" viewBox="0 0 650 155" role="img" aria-label="Sample accuracy trend rising from 61 percent to 78 percent over 30 days; not a live measurement"><g stroke="#edf1f4"><path d="M35 20H630M35 70H630M35 120H630"/></g><text x="0" y="24">90%</text><text x="0" y="74">75%</text><text x="0" y="124">60%</text><path d="M35 116L90 113L145 102L200 104L255 92L310 80L365 86L420 63L475 62L530 58L580 64L630 59" fill="none" stroke="#258c8b" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="630" cy="59" r="4" fill="#258c8b"/><text x="35" y="148">17 Aug</text><text x="205" y="148">27 Aug</text><text x="405" y="148">6 Sep</text><text x="585" y="148">16 Sep</text></svg>`}
function overview(){const open=drifts.filter(d=>!isResolved(d.id));const qualified=state.leads.filter(x=>x==='Qualified').length+9;return heading('ANSWER MANAGEMENT / NORTHSTAR IT','Good morning, Dana.','The answers are getting better. Here’s what needs your judgment.',btn('Weekly digest ↗','digest','','primary'))+`<div class="cards">${metric('Answer accuracy','78<span>%</span>','↑ 17 points from the sample baseline','31 of 40 scored facts correct · 96% coverage','◎')}${metric('Can AI read your site?',`${accessCount()}<span> / 5 engines</span>`,state.blocked?'Claude reader blocked':state.probePending?'Waiting for observed Claude fetch':'Probe + observed reads confirmed',state.blocked?'Sample host response: 429':'Google · ChatGPT · Copilot · Perplexity · Claude','⊞')}${metric('Surfaces in sync',`${41+state.resolved.length}<span> / 44 fields</span>`,`${open.length} open drift events${state.blocked?' + 1 access event':''}`,`${open.filter(x=>x.severity==='Critical').length+(state.blocked?1:0)} critical · across 8 surfaces`,'⇄')}${metric('Qualified enquiries',String(qualified),'3 said they used an AI assistant','0 verified AI visits reached the form · last 28 days','♧')}</div><div class="grid"><div><section class="card focus"><div class="row"><p class="eyebrow">YOUR NEXT DECISION</p>${badge(state.accessApproved?'Access policy approved':'5 MINUTES · REVIEW FIRST')}</div><h2>${state.blocked?'Help Claude read your site again.':!state.accessApproved?'Let the right AI readers in. Keep control.':'Make your managed IT answer more specific.'}</h2><p>${state.blocked?'The sample host returns 429. Review the support request and confirm the fix with both a probe and an observed read.':!state.accessApproved?'Review exactly how Answority would allow answer readers, limit training crawlers and preserve search access.':'The diagnosis points to answers being shown without a click. Review a focused change backed by your company facts.'}</p>${go(state.blocked?'Review access issue →':!state.accessApproved?'Review AI access settings →':'Review the page change →',state.blocked||!state.accessApproved?'access':'review/managed','light')}<div class="mini-divider"><span>Owner approval required</span><span>${state.accessApproved?'Policy v2 · approved in demo':'Policy v1 → v2 · proposed'}</span></div></section><section class="card spaced"><div class="section-head"><h2>Also on your list</h2>${badge('YOUR WEEK')}</div><div class="task"><span class="task-icon red">!</span><div class="task-copy"><p>${isResolved('phone')?'Old phone number corrected in demo':'ChatGPT is repeating an old phone number'}</p><small>Bing Places · ${isResolved('phone')?'sample re-check complete':'critical drift · guided fix ready'}</small></div>${go('Review →','sync','small')}</div><div class="task"><span class="task-icon">?</span><div class="task-copy"><p>Does the after-hours line cover P2 tickets?</p><small>${state.interview?'Response captured · awaiting review':'One fact question · about 1 minute'}</small></div>${btn('Answer →','interview','','small')}</div><div class="task"><span class="task-icon">↗</span><div class="task-copy"><p>Put qualified support commitments on the page</p><small>${state.published.length+1} of 4 page changes used this month</small></div>${go('Review →','review/managed','small')}</div></section><section class="card spaced"><div class="section-head"><h2>Accuracy is improving in the sample</h2>${go('Open evidence ↗','answers','link')}</div>${trend()}<div class="legend"><span><i></i>Trailing 14-day accuracy, displayed across 30 days</span><span>Sample observations · no attributed lift</span></div></section></div><div><section class="card"><div class="section-head"><h2>Work with a receipt</h2>${badge('SEPTEMBER')}</div>${[['Page changes verified',1+state.published.length],['Profile fields corrected',3+state.resolved.filter(x=>x==='hours').length],['LinkedIn drafts exported','6 / 12'],['Internal links checked','9 / 20'],['Guided fixes closed',2+state.resolved.filter(x=>x!=='hours').length]].map(([a,b])=>`<div class="work-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}<p class="work-caption">Seeded work + your demo actions. Open the Owner Report for receipts and limitations.</p>${go('Open Owner Report →','results','link')}</section><section class="card spaced"><div class="section-head"><h2>Reader activity</h2>${badge('90 DAYS')}</div><div class="bar-row"><span>Training</span><div class="bar"><span style="width:58%;background:#aabeca"></span></div><strong>58%</strong></div><div class="bar-row"><span>Search</span><div class="bar"><span style="width:27%;background:#638fa8"></span></div><strong>27%</strong></div><div class="bar-row"><span>Answer readers</span><div class="bar"><span style="width:11%"></span></div><strong>11%</strong></div><div class="bar-row"><span>Unknown</span><div class="bar"><span style="width:4%;background:#d6b980"></span></div><strong>4%</strong></div><p class="work-caption">Share of 1,000 sample requests. Requests are not people or enquiries.</p>${go('Explore AI visitor report →','visitors','link')}</section><section class="card spaced"><p class="eyebrow">YOUR NEXT CHECK-IN</p><h2>What did the owner get?</h2><p class="subtitle" style="margin:12px 0 18px">Corrected facts, readable pages and enquiries with a source. No invented return on investment.</p>${go('Preview the report ↗','results','small')}</section></div></div>`}
function diagnosis(){return heading('UNDERSTAND','Why did enquiries change?','Two working hypotheses. Rule out broken measurement before changing content.',badge(state.diagnosis||'Needs your review',state.diagnosis?'good':'warn'))+`<div class="split">${card('1. Answer shown, click lost',`${badge('Likely','blue')}<p class="fact-value">The page is appearing more often in AI answers, while fewer people click through.</p><div class="checklist"><div><b>For:</b> AI-surface impressions +3.1× in the sample.</div><div><b>For:</b> Search clicks down 24%, rankings broadly stable.</div><div><b>Against:</b> Seasonal buyer mix could also affect clicks.</div></div><div class="note">Smallest useful action: add sourced support commitments and service coverage to the existing answer.</div>${go('Review recommended change →','review/managed','primary')}`)}${card('2. Company facts disagree',`${badge('Plausible','warn')}<p class="fact-value">An old phone number appears in a sampled ChatGPT answer and in Bing Places.</p><div class="checklist"><div><b>For:</b> The old number matches the directory entry.</div><div><b>Against:</b> The answer does not prove which source was used.</div><div><b>Next:</b> Correct the listing, then observe new answers.</div></div>${go('Open surface drift →','sync')}`)}</div><section class="card spaced"><h2>Checked before recommending content</h2>${table(['Check','Sample evidence','Decision'],[['Measurement','Plugin form counts match analytics.','Ruled out'],['Technical status','Page returns 200 and remains indexable.','Ruled out'],['Reader access',`${accessCount()} of 5 engines have both a probe and observed read.`,accessCount()===5?'Ruled out':'Fix / verify access first']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`))}<div class="row spaced">${btn('Accept diagnosis','diagnosis','Accepted','primary')}${btn('Correct explanation','diagnosis','Corrected')}${btn('Dismiss with reason','diagnosis','Dismissed')}</div>${state.diagnosisReason?`<div class="note">Your review: ${esc(state.diagnosisReason)}</div>`:''}</section>`}
const engines=[{name:'ChatGPT',score:'70%',counts:'7 correct / 10 scored',coverage:'96%',label:'Interface sample',verdict:'Wrong',assertion:'“Call Northstar on (303) 555-0114.”',claim:'Phone · +1 (303) 555-0142',source:'Bing Places — likely source'},{name:'Gemini',score:'90%',counts:'9 correct / 10 scored',coverage:'100%',label:'Interface sample',verdict:'Stale',assertion:'“Northstar provides standard support 24 hours a day.”',claim:()=>`Standard hours · ${state.hours}`,source:'Google Business Profile — likely source'},{name:'Google AI',score:'80%',counts:'8 correct / 10 scored',coverage:'96%',label:'AI Overview / AI Mode',verdict:'Omitted',assertion:'The answer names Denver but omits Boulder.',claim:'Service area · Denver–Boulder metro',source:'Service overview page'},{name:'Perplexity',score:'70%',counts:'7 correct / 10 scored',coverage:'92%',label:'API sample',verdict:'Unverifiable',assertion:'“All security incidents are resolved within an hour.”',claim:'No approved resolution guarantee',source:'Source not established'}];
function answers(){const selected=engines.filter(e=>answerFilter==='All engines'||e.name===answerFilter);return heading('OBSERVE','What do the answers get right?','Every verdict opens the answer, the assertion and the approved fact.',btn('How the score works','score'))+`<div class="cards">${engines.map(e=>metric(e.name,e.score,e.counts,`${e.label} · ${e.coverage} coverage`,'◎')).join('')}</div><div class="filters"><label for="engine-filter">Engine</label><select id="engine-filter">${['All engines',...engines.map(e=>e.name)].map(n=>`<option ${answerFilter===n?'selected':''}>${n}</option>`).join('')}</select><span class="help">Trailing 14 days · 100 attempted observations per engine · illustrative</span></div><section class="card">${table(['Engine / surface','Observed assertion','Verdict','Evidence'],selected.map(e=>`<tr><td><strong>${e.name}</strong><small>${e.label}</small></td><td>${esc(e.assertion)}<small>${e.source}</small></td><td>${badge(e.verdict,e.verdict==='Wrong'?'bad':'warn')}</td><td>${btn('Open evidence','assertion',e.name,'small')}</td></tr>`))}<div class="note">Accuracy = correct ÷ (correct + stale + wrong + omitted). Unverifiable claims request a fact; declined answers affect coverage. Scores are hidden below 20 observations. Demo repairs do not immediately change engine answers or this score.</div></section>`}
function facts(){const items=[['Service area','Denver–Boulder metro','Service agreement §2 · approved by Dana · 7 Sep','Approved'],['Support hours',state.hours,`Support schedule · version ${state.factVersion} · ${state.factVersion>1?'approved in demo':'7 Sep'}`,'Approved'],['P1 response commitment','After-hours line for P1 incidents, subject to the client service agreement. P2 cover is not confirmed.','Response policy §4 · approved by Dana · 7 Sep','Approved'],['Pricing band','$125–$185 / user / month; 25-user minimum; onboarding quoted separately; 12-month initial term.','Proposed commercial schedule · owner approval required',state.pricing==='approved'?'Approved':state.pricing==='declined'?'Declined':'Proposed'],['Contact phone','+1 (303) 555-0142','Contact register · approved by Dana · 7 Sep','Approved'],['Booking link','https://northstar.example/book','Example booking destination · approved by Dana · 7 Sep','Approved']];return heading('COMPANY FACTS','Approve once. Know everywhere it appears.','Your source passages, review dates and dependent pages in one place.',btn('Answer a fact question','interview','','primary'))+`<div class="thirds">${items.map((f,i)=>card(f[0],`${badge(f[3],f[3]==='Approved'?'good':'warn')}<p class="fact-value">${esc(f[1])}</p><div class="source">${esc(f[2])}<br>Review due 7 Oct 2026 · ${i===1?'7':'3'} mapped uses</div><div class="row spaced">${btn('Source & uses','fact-detail',String(i),'small')}${i===1?btn('Change hours','hours','','small'):''}${i===3&&state.pricing==='proposed'?btn('Review pricing','pricing','','small primary'):''}</div>`)).join('')}</div>${state.interview?`<div class="note">Proposed expert response: “${esc(state.interview)}”. Captured for reviewer approval; not added to publishable facts.</div>`:''}`}
function sync(){return heading('SURFACE SYNC','One truth, across every surface.','Eight surfaces, 44 tracked fields. Guided fixes stay open until a re-check.',badge(`${41+state.resolved.length} / 44 fields in sync`,'good'))+`<section class="card">${table(['Surface / field','Observed → approved','Severity','Action'],drifts.map(d=>`<tr><td><strong>${d.surface}</strong><small>${d.field} · ${d.mechanism}</small></td><td>${isResolved(d.id)?'<span class="muted">Sample re-check matches</span>':`<span class="danger-text">${esc(d.old)}</span> →`}<br><strong>${esc(typeof d.correct==='function'?d.correct():d.correct)}</strong></td><td>${badge(isResolved(d.id)?'Closed':d.severity,isResolved(d.id)?'good':d.severity==='Critical'?'bad':'warn')}</td><td>${btn(isResolved(d.id)?'View receipt':state.guided.includes(d.id)?'Re-check sample':'Review fix','drift',d.id,'small')}</td></tr>`))}<div class="note">A requested correction does not prove an external listing changed. Guided updates are explicitly re-checked using a sample response.</div></section><div class="thirds spaced">${['Website + Fact Pages','LinkedIn','Yelp','Facebook','UpCity'].map(n=>card(n,`${badge('Sample in sync','good')}<p class="source">Approved facts matched in the seeded snapshot.</p>`)).join('')}${card('AI access',`${badge(`${accessCount()} of 5 engines readable`,accessCount()===5?'good':'bad')}<p class="source">Separate access check, outside the 44-field total.</p>${go('Open access settings →','access','link')}`)}</div>`}
const questions=[['Discover','Best managed IT provider in Denver?','ChatGPT','No','Yes','Summit Systems','Clutch · Denver MSP list'],['Compare','Northstar IT vs Summit Systems?','Gemini','Yes','Yes','Summit Systems','Google Business Profile'],['Cost','What does managed IT cost per user in Denver?','Perplexity','No','No','Front Range Tech','UpCity · pricing guide'],['Switch','How do I switch IT providers in Boulder?','Google AI','No','No','PeakDesk IT','Reddit · local discussion'],['Implementation','How does Northstar onboard a new client?','ChatGPT','Yes','Yes','—','Northstar service page'],['Compliance','Who supports compliance-focused IT teams in Denver?','Gemini','No','Yes','Summit Systems','Expertise.com · provider list']];
function questionView(){const rows=questions.filter(q=>questionFilter==='All intents'||q[0]===questionFilter);return heading('BUYER QUESTIONS','Show up where the shortlist is made.','Named, cited and accurate are different signals. Explore the sources behind the answers.',btn(`Question panel v${state.panel}`,'panel'))+`<div class="filters"><label for="intent-filter">Buyer intent</label><select id="intent-filter">${['All intents','Discover','Compare','Cost','Switch','Implementation','Compliance'].map(n=>`<option ${questionFilter===n?'selected':''}>${n}</option>`).join('')}</select>${badge('Fictional competitors & source observations')}</div><section class="card">${table(['Question / engine','Named','Cited','Named instead','Cited source'],rows.map(q=>`<tr><td><strong>${q[1]}</strong><small>${q[0]} · ${q[2]}${q[2]==='Perplexity'?' (API)':''}</small></td><td>${badge(q[3],q[3]==='Yes'?'good':'')}</td><td>${badge(q[4],q[4]==='Yes'?'good':'')} ${q[3]==='No'&&q[4]==='Yes'?'<small>Cited without being named</small>':''}</td><td>${q[5]}</td><td>${btn(q[6],'source-gap',String(questions.indexOf(q)),'small')}</td></tr>`))}<div class="note">A source gap becomes a guided action or a draft for a human to review and post. Answority does not post to communities automatically.</div></section>${state.bookmarked.length?card('Saved guided actions',state.bookmarked.map(i=>`<div class="work-row"><span>${questions[i][6]}</span>${badge('Saved for human review','blue')}</div>`).join(''),'spaced'):''}`}
function plan(){return heading('MONTHLY PLAN','Four useful changes. A clear reason for each.','Three priorities plus one seeded example update. Review, swap or postpone the work.',btn('Scoring explained','priority'))+`<section class="card">${plans.map(p=>`<div class="task"><span class="task-icon">${p.score}</span><div class="task-copy"><p>${p.title}</p><small>${p.path} · ${p.type}</small><p class="muted" style="font-weight:400;margin-top:8px">${p.reason}</p></div>${state.published.includes(p.id)?badge('Demo verified','good'):go('Review →','review/'+p.id,'small')}</div>`).join('')}<div class="note">${1+state.published.length} of 4 page changes used. Draft generation is simulated. Units are consumed once on a simulated verification; retries do not consume another unit.</div></section>`}
function draftText(p){return state.drafts[p.id]??p.text()}
function review(id){const p=plans.find(x=>x.id===id)||plans[0],done=state.published.includes(p.id);return heading('REVIEW THE CHANGE',p.title,p.path,go('← Monthly plan','plan'))+`<div class="steps"><span>1 · Evidence attached</span><span class="active">2 · Review exact text</span><span>3 · Approve</span><span>4 · Simulate verification</span></div><div class="note">${p.reason} Destination snapshot: v12. Policy: review-first v1. Current company fact version: ${state.factVersion}.</div><div class="split">${card('Current page',`<div class="copy old">${esc(p.old)}</div><div class="source">Snapshot captured 15 Sep 2026 · fictional website</div>`)}${card('Proposed change',`<label for="draft">Editable page copy</label><textarea id="draft" class="editor" data-id="${p.id}" ${done?'readonly':''}>${esc(draftText(p))}</textarea><div class="source">Claims: support hours · service area · phone${p.id==='managed'?' · qualified P1 cover':''}${p.id==='pricing'?' · pricing band':''}. Every draft edit invalidates approval.</div>`)}</div><section class="card spaced"><div class="section-head"><h2>Your approval binds this version</h2>${badge(done?'Demo verified':state.approvals[p.id]?'Approved':'Needs review',done||state.approvals[p.id]?'good':'warn')}</div><p class="subtitle">Review facts, at least two sourced specifics, the opening answer and preserved contact details. Automated content validation is not implemented in this demo.</p><div class="row spaced">${done?go('Open the publication receipt →','results','primary'):btn(state.approvals[p.id]?'Publish demo change →':'Approve exact draft','approve-draft',p.id,'primary')}${done?'':btn('Save draft','save-draft',p.id)}${go('Inspect company facts','facts')}</div>${state.paused?'<div class="note warn">Publishing is paused in Controls.</div>':''}</section>`}
function access(){const status=state.blocked?'429':state.probePending?'200 · pending':'200';return heading('AI ACCESS SETTINGS','Let answer readers in. Keep control.','Check reachability and observed reads separately. Search engines always stay allowed.',btn(state.blocked?'Simulate host fix':state.probePending?'Confirm observed read':'Simulate a host block',state.blocked?'host-fixed':state.probePending?'observed':'host-block'))+`<div class="split"><section class="card"><div class="section-head"><h2>Who can read your site?</h2>${badge(state.accessApproved?'Policy approved':'Changes need approval',state.accessApproved?'good':'warn')}</div><div class="setting"><div><h3>Search engines</h3><p>Google, Bing and documented search readers.</p></div>${badge('Always allow','good')}</div><div class="setting"><div><h3>Answer readers</h3><p>Read pages when a buyer asks an assistant.</p></div><select id="answer-policy" aria-label="Answer reader policy"><option ${state.answerReaders==='Allow'?'selected':''}>Allow</option><option ${state.answerReaders==='Allow with generous limit'?'selected':''}>Allow with generous limit</option></select></div><div class="setting"><div><h3>Training crawlers</h3><p>Publish your preference for training-only readers.</p></div><select id="training-policy" aria-label="Training reader policy"><option ${state.training==='Limit'?'selected':''}>Limit</option><option ${state.training==='Allow'?'selected':''}>Allow</option></select></div><div class="setting"><div><h3>Unknown automation</h3><p>Some unknown readers may be useful assistants.</p></div>${badge('Rate-limit','blue')}</div><div class="row spaced">${btn('Review proposed settings diff','access-diff','','primary')}</div><p class="help">Demo only. No server, firewall or robots file is changed.</p></section><section class="card"><div class="section-head"><h2>Can each engine read your pages?</h2>${badge(`${accessCount()} / 5`,accessCount()===5?'good':'warn')}</div>${table(['Reader','Home','Services','Pricing','Contact','Facts'],['Google','ChatGPT','Copilot','Perplexity','Claude'].map(n=>`<tr><td><strong>${n}</strong></td>${Array.from({length:5},()=>`<td>${badge(n==='Claude'?status:'200',n==='Claude'&&(state.blocked||state.probePending)?state.blocked?'bad':'warn':'good')}</td>`).join('')}</tr>`),'reader-grid')}<div class="note">Green requires a successful probe and the engine’s observed read. ${state.blocked?'Claude: both sample checks return 429.':state.probePending?'Claude probe succeeds, but an observed read is still missing.':'Both checks succeed in this sample.'}</div></section></div><section class="card spaced"><div class="section-head"><h2>Hosting & security findings</h2>${badge('Sample detection')}</div><div class="thirds"><div><h3>WP Engine</h3><p class="subtitle">${state.blocked?'Platform-level block on Claude. A robots setting cannot override this host response.':state.probePending?'Host fix reported. Wait for evidence from an observed read.':'Example Claude block resolved on 6 Sep; both checks confirmed.'}</p><div class="spaced">${btn('Preview host email','host-email','','small')}</div></div><div><h3>Wordfence</h3><p class="subtitle">A burst limiter may throttle legitimate readers. Review its allow-list before changing rules.</p><div class="spaced">${btn('View guidance','wordfence','','small')}</div></div><div><h3>Cloudflare</h3><p class="subtitle">Not connected. Core shows guidance; settings push belongs to a later connected implementation.</p><div class="spaced">${go('Review connections →','connections','link')}</div></div></div></section>`}
function factData(){return {company:'Northstar IT',serviceArea:'Denver–Boulder metro',supportHours:state.hours,phone:'+1 (303) 555-0142',booking:'https://northstar.example/book',...(state.pricing==='approved'?{pricing:'$125–$185 per user per month; 25-user minimum; onboarding quoted separately; 12-month initial term'}:{}),version:state.factVersion,lastReviewed:'2026-09-16',demo:true}}
function factPages(){const f=factData();let content;if(tab==='visible')content=`<div class="copy"><h2>Northstar IT · Company facts</h2><p class="help">Last reviewed 16 September 2026 · version ${f.version}</p><p>Service area: ${f.serviceArea}</p><p>Support hours: ${esc(f.supportHours)}</p><p>Phone: ${f.phone}</p><p>Booking: ${f.booking}</p>${f.pricing?`<p>Pricing: ${f.pricing}</p>`:'<p>Pricing band not published — owner approval required.</p>'}</div>`;else if(tab==='markdown')content=`<pre class="code">${esc(`# Northstar IT\n\nLast reviewed: ${f.lastReviewed}\nVersion: ${f.version}\n\n${Object.entries(f).filter(([k])=>!['company','version','lastReviewed','demo'].includes(k)).map(([k,v])=>`- ${k}: ${v}`).join('\n')}`)}</pre>`;else content=`<pre class="code">${esc(JSON.stringify(tab==='structured'?{'@context':'https://schema.org','@type':'Organization',name:f.company,areaServed:f.serviceArea,telephone:f.phone,description:`Support hours: ${f.supportHours}${f.pricing?'; Pricing: '+f.pricing:''}`,url:f.booking,dateModified:f.lastReviewed}:f,null,2))}</pre>`;return heading('FACT PAGES','One source. Four consistent forms.','Preview the same approved facts as a page and as readable data.',btn('Download facts sample','download-facts'))+`<div class="tabs" role="group" aria-label="Fact format">${[['visible','Visible page'],['machine','Machine-readable copy'],['markdown','Markdown'],['structured','Structured data']].map(([id,name])=>`<button data-action="fact-tab" data-id="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div><section class="card"><div class="section-head"><h2>Approved facts · version ${f.version}</h2>${badge('Shared source','good')}</div>${content}<div class="note">These are browser previews, not live endpoints. A production plugin would render HTML without JavaScript, regenerate all forms together and notify search services. This static demo does not publish endpoints or send notifications.</div></section>`}
function visitors(){const weekly=visitorPeriod==='7';const counts=weekly?[['ChatGPT',38,7,1],['Google',31,9,1],['Copilot',15,3,0],['Perplexity',12,4,0],['Claude',5,0,0]]:[['ChatGPT',142,29,3],['Google',108,34,2],['Copilot',64,12,0],['Perplexity',53,18,0],['Claude',21,0,0]];return heading('AI VISITOR REPORT','Who read you. What followed.','Reader activity, answers and enquiries sit alongside each other — not in a conversion funnel.',`<select id="visitor-period" aria-label="Visitor reporting period"><option value="90" ${!weekly?'selected':''}>Last 90 days</option><option value="7" ${weekly?'selected':''}>Last 7 days</option></select>`)+`<div class="cards">${metric('Verified AI visits','0','Signature verification is not implemented','Phase 2 capability · zero means zero','✓')}${metric('Declared readers',weekly?'74':'312','Documented identity in sample logs','Not independently signature-verified','◷')}${metric('Unknown readers',weekly?'9':'41','Identity could not be established','Not treated as buyers','?')}${metric('Answer engine access',`${accessCount()}<span> / 5</span>`,'Both checks required for green','Successful probe + observed read','⊞')}</div><section class="card"><div class="section-head"><h2>Three different counts, by engine</h2>${badge(weekly?'7-day sample':'90-day sample')}</div>${table(['Engine','Fact-page requests','Answers naming or citing you','Tagged enquiries'],counts.map(r=>`<tr>${r.map((c,i)=>`<td>${i===0?'<strong>'+c+'</strong>':c}</td>`).join('')}</tr>`))}<div class="note">Not a conversion rate. Requests, sampled answers and tagged enquiries have different denominators and cannot be joined into a person-level journey. Counts of declared readers refer to distinct sample readers; request counts can be higher.</div></section><div class="split spaced">${card('Reader share by purpose',`${[['Training',58],['Search',27],['Answer readers',11],['Unknown',4]].map(([n,v])=>`<div class="bar-row"><span>${n}</span><div class="bar"><span style="width:${v}%"></span></div><strong>${v}%</strong></div>`).join('')}<p class="help">Fixed 90-day sample: 1,000 requests. Not total “AI traffic”.</p>`)}${card('Pages answer readers requested most',table(['Page','Requests'],(weekly?[['/pricing',28],['/managed-it-services',24],['/contact',19],['/facts',17],['/',13]]:[['/pricing',148],['/managed-it-services',92],['/contact',61],['/facts',53],['/',34]]).map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`)))}</div>`}
function enquiries(){return heading('ENQUIRY CAPTURE','Make the next step easy to find.','Readiness and source attribution. No claim that an AI reader became a buyer.',btn('Try sample enquiry form','enquiry-form','','primary'))+`<div class="cards">${metric('Buyer-reported AI','3','The buyer selected an assistant','Self-reported source, not verified referral','♧')}${metric('AI-referred','2','A referrer identified an assistant','Separate from self-reported answers','↗')}${metric('Direct or search','6','Source class recorded','Illustrative qualified enquiries','⌕')}${metric('Verified AI at form','0','No verified visits recorded','Signature verification is Phase 2','✓')}</div><div class="split">${card('Enquiry readiness',`<div class="checklist"><div><b>✓</b> Contact phone matches the approved register.</div><div><b>✓</b> Booking destination stored as a company fact.</div><div><b>${state.pricing==='approved'?'✓':'○'}</b> Pricing band ${state.pricing==='approved'?'approved for the fact page':'awaits owner approval'}.</div><div><b>○</b> Call-answer test and quote-readiness review pending.</div><div><b>○</b> Server-handled, JavaScript-free form is a production capability.</div></div>${go('Review contact and pricing facts →','facts','link')}`)}${card('Source handoff',`<p class="fact-value">Every enquiry keeps its source class and the buyer’s own answer.</p><div class="copy">Source class: buyer-reported assistant<br>Buyer answer: ChatGPT<br>Landing page: /managed-it-services<br>CRM destination: HubSpot (simulated)</div><div class="note">No personal contact details are needed for the demo. Trying the form creates a preview payload only.</div>`)}</div><section class="card spaced"><h2>Qualify the sample enquiries</h2>${table(['Enquiry','Source','Qualification'],[['Operations director','Buyer-reported assistant · ChatGPT'],['Finance lead','AI-referred · Gemini'],['Office manager','Direct / search'],['Job applicant','Direct / search']].map((r,i)=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td><select data-lead="${i}" aria-label="Qualification for ${r[0]}">${['Qualified','Pending','Unqualified'].map(s=>`<option ${state.leads[i]===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`))}<p class="help">Qualification changes update the overview count. The source summary above remains the labelled 28-day baseline fixture.</p></section>`}
function reportText(){return `ANSWORITY DASHBOARD — NORTHSTAR IT\nOwner Report · September 2026 · SAMPLE DATA\n\nAccuracy: 61% to 78% (31/40 scored facts; 96% coverage).\nAccess: ${accessCount()} of 5 engines have both successful probe and observed read.\nSurface fields in sync: ${41+state.resolved.length}/44.\nPage changes: ${1+state.published.length}/4 including seeded example.\nEnquiry baseline: 3 buyer-reported assistant, 2 AI-referred, 6 direct/search.\nVerified AI visits reaching form: 0.\n\nOutcome: INCONCLUSIVE. These observations do not establish incremental impact.\nNext: review pricing, correct outstanding drift and observe the fixed question panel.\n\nDemo activity:\n${state.events.map(e=>'- '+e.title).join('\n')||'No new demo actions.'}\n\nNo external account was connected, no live publication occurred, and no engine answers were refreshed.`}
function results(){return heading('OWNER REPORT','What changed. What we can prove.','A readable account of the work, the observations and the next decision.',btn('Download report','download-report','','primary'))+`<section class="card"><p class="eyebrow">NORTHSTAR IT / SEPTEMBER 2026</p><h2>More accurate answers. A clearer path to contact.</h2><p class="report-intro">The sample Answer Accuracy Score moved from <strong>61% to 78%</strong>. ${accessCount()} of 5 answer engines can read the site with both checks confirmed. The enquiry baseline records <strong>3 buyers who reported using an AI assistant</strong>, 2 AI referrals and 6 direct or search enquiries.</p><div class="note">Observed comparisons only. Incremental impact remains inconclusive. Zero verified AI visits reached the enquiry form. These are fictional results, not an actual return on investment.</div></section><div class="split spaced">${card('Completed work & receipts',`${table(['Change','Status','Receipt'],[['Managed services overview','Seeded verified example','baseline'],...state.published.map(id=>[plans.find(p=>p.id===id).title,'Demo verified',id])].map(r=>`<tr><td>${r[0]}</td><td>${badge(r[1],'good')}</td><td>${btn('Open','receipt',r[2],'small')}</td></tr>`))}<div class="source">Corrections to external surfaces are tracked separately from the monthly page allowance.</div>`)}${card('Next month’s decisions',`<div class="checklist"><div><b>01</b> Resolve remaining profile drift and re-check.</div><div><b>02</b> Review the proposed pricing band.</div><div><b>03</b> Keep the buyer question panel stable.</div><div><b>04</b> Evaluate changes at 7, 14, 28 and 42 days.</div></div>${go('Open monthly plan →','plan','link')}`)}</div><section class="card spaced"><h2>Demo activity trail</h2>${state.events.length?state.events.slice(0,15).map(e=>`<div class="work-row"><span>${esc(e.title)}</span><small class="muted">${e.detail}</small></div>`).join(''):'<p class="subtitle spaced">Your approvals and simulated corrections will appear here.</p>'}</section>`}
function connections(){const descriptions={'WordPress plugin':'Unlocks crawl, fact-page publishing, form capture and reader checks. Without it: previews only.','Search Console':'Adds page/query performance and diagnostic context. Without it: sample public audit only.','Google Business Profile':'Allows approved fact corrections. Without it: guided copy and re-check.','Bing Places':'Enables a supported listing connection. Otherwise use a guided update.','HubSpot':'Receives enquiry source classes. Without it: export preview only.','LinkedIn':'Supports approved posts when app access is available. Otherwise export drafts.'};return heading('SETUP','Connect what makes the next action possible.','All toggles simulate connection states. No credentials or permissions are requested.')+`<div class="connection-grid">${Object.entries(descriptions).map(([name,desc])=>`<section class="card"><h2>${name}</h2><p>${desc}</p>${badge(state.connections[name]?'Demo connected':'Not connected',state.connections[name]?'good':'warn')}<div class="spaced">${btn(state.connections[name]?'Disconnect demo':'Connect demo','connection',name,'small')}</div></section>`).join('')}</div><div class="note">WordPress connection is required for simulated page publication. Google Business Profile connection is required for its simulated correction. Host and security findings are available in AI access.</div>`}
function audit(){return heading('FREE ANSWER AUDIT','Start with the answers about your business.','Explore the fictional Northstar audit. No account, scan or external connection required.')+`<section class="card"><label for="audit-domain">Example website</label><form id="audit-form" class="audit-input"><input id="audit-domain" value="northstar.example" readonly><button class="button primary" type="submit">Run sample audit →</button></form><p class="help">This demo is restricted to the fictional company. The result is a seeded pre-fix snapshot.</p></section>${state.auditRun?`<div class="cards spaced">${metric('Baseline accuracy','61<span>%</span>','Before the example improvements','Four engines · sample snapshot')}${metric('Engine access','4<span> / 5</span>','Claude reader returned 429','Historical pre-fix sample','!')}${metric('Fact errors','7','Wrong, stale or omitted','Inspect the assertions before action','◎')}${metric('Buyer-question presence','9<span>%</span>','Named in the fixed sample','Sample baseline, not market share','◇')}</div><div class="split">${card('First errors to investigate','<p class="fact-value">Old phone number in ChatGPT. Overstated support hours in Gemini. Missing Boulder coverage.</p>'+go('Explore current answer evidence →','answers','primary'))}${card('First access issue','<p class="fact-value">The baseline host response for Claude was 429 on all five pages. Current dashboard state is shown separately.</p>'+go('Open current access checks →','access'))}</div>`:''}`}
function controls(){return heading('WORKSPACE CONTROLS','Automation with a visible boundary.','Explicit approvals, source versions and a way to pause.')+card('Publishing policy',`<div class="setting"><div><h3>Pause all simulated publishing</h3><p>Blocks page publication and policy or API-style writes. Guided drafts remain readable.</p></div><button role="switch" aria-label="Pause publishing" aria-checked="${state.paused}" class="switch" data-action="pause"></button></div><div class="setting"><div><h3>Review first</h3><p>Prices, promises, comparisons, certifications and new pages always require review.</p></div>${badge('Required','good')}</div><div class="setting"><div><h3>Monthly page allowance</h3><p>One seeded example update; three remaining demonstration changes.</p></div><strong>${1+state.published.length} / 4</strong></div><div class="setting"><div><h3>Roadmap boundaries</h3><p>Signature verification, automatic host settings and live integrations are not implemented.</p></div>${badge('Demo only')}</div><div class="row spaced">${btn('Reset this version','reset','','danger')}<a class="button small" href="../index.html">Answority home ↗</a></div>`)}
function render(){const [raw,id]=location.hash.slice(1).split('/'),route=raw||'overview';const map={overview,diagnosis,answers,questions:questionView,plan,facts,sync,'fact-pages':factPages,access,visitors,enquiries,results,connections,audit,controls};const active=route==='review'?'plan':route;$('#navigation').innerHTML=navData().map(item=>item.length===1?`<div class="nav-group">${item[0]}</div>`:`<a href="#${item[0]}" ${active===item[0]?'class="active" aria-current="page"':''}><span class="nav-icon">${item[1]}</span>${item[2]}${item[0]==='sync'?`<span class="nav-number">${3-state.resolved.length}</span>`:''}</a>`).join('');$('#crumb').textContent=route==='review'?'Review change':navData().find(n=>n[0]===route)?.[2]||'Overview';$('#allowance').value=1+state.published.length;$('#allowance-label').textContent=`${1+state.published.length} of 4 page changes used · demo`;$('#main').innerHTML=route==='review'?review(id):(map[route]||overview)();}
function download(filename,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function finish(){save();$('#dialog').close();render()}
function driftDialog(id){const d=drifts.find(x=>x.id===id);if(isResolved(id))return modal('Sample correction receipt',`<p>${d.surface} · ${d.field}</p><p>The sample re-check matches: <strong>${esc(typeof d.correct==='function'?d.correct():d.correct)}</strong>.</p><div class="note">No external listing was changed or fetched. Engine answers remain unchanged until a new observation; this demo does not collect one.</div>`);modal(`${d.surface}: ${d.field}`,`<p>${d.detail}</p><div class="copy"><strong>Observed:</strong> ${esc(d.old)}<br><strong>Approved:</strong> ${esc(typeof d.correct==='function'?d.correct():d.correct)}</div>${id==='hours'?'<p>Approve a simulated profile correction. The demo read-back will match the approved hours.</p>':'<p>Copy the exact approved value into the listing in a real workflow. Here, mark the guided step complete, then run the sample re-check.</p>'}<div class="row">${id==='hours'?btn('Approve & simulate correction','resolve',id,'primary'):state.guided.includes(id)?btn('Run sample re-check','resolve',id,'primary'):btn('Mark guided step complete','guided',id,'primary')}</div>`)}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;switch(action){
case 'close':$('#dialog').close();break;
case 'tour':modal('Explore the new Answority',`<ol><li>Review the <b>AI access</b> diff and approve the sample policy.</li><li>Try a host block, a reported fix and an observed read. All three states stay distinct.</li><li>Correct a profile in <b>Surface sync</b>; guided work needs a re-check.</li><li>Change support hours in <b>Company facts</b> and inspect every dependent surface.</li><li>Review and approve a page in <b>Monthly plan</b>, then simulate publication.</li><li>Explore <b>AI visitor report</b>, enquiry sources and download the <b>Owner Report</b>.</li></ol><div class="note">State is saved only in this browser, separately from the original demo. All accounts, sources and results are fictional.</div>`);break;
case 'digest':modal('Your weekly digest',`<p>Accuracy: <b>78%</b>, up from 61% in the sample. Reader access: <b>${accessCount()} of 5</b>. ${3-state.resolved.length} profile drift events remain.</p><ol><li>Review the proposed AI access policy.</li><li>Correct the outdated Bing Places phone number.</li><li>Answer the P2 support coverage question.</li></ol><p>Target routine: ten minutes. No completed-time claim is made.</p>${go('Open Owner Report →','results','primary')}`);break;
case 'score':modal('An accuracy score you can inspect','<p>31 correct facts ÷ 40 scored facts = 77.5%, rounded to 78%.</p><p>The 40 comprise 31 correct, 3 stale, 3 wrong and 3 omitted. The separately shown unverifiable assertion is excluded.</p><p>Coverage: 384 successful observations ÷ 400 attempted = 96%, over the trailing 14 days. Each engine has at least 20 observations.</p><div class="note">Illustrative fixtures. Declined or failed answers affect coverage, never turn into incorrect facts.</div>');break;
case 'assertion':{const e=engines.find(x=>x.name===id);modal(`${e.name} · assertion evidence`,`<p>${badge(e.label,'blue')} ${badge(e.verdict,'warn')}</p><div class="copy">${esc(e.assertion)}</div><label>Approved fact</label><p>${esc(typeof e.claim==='function'?e.claim():e.claim)}</p><p>Likely source: ${e.source}. Sample captured 15 Sep; no source attribution is proved.</p>${e.verdict==='Unverifiable'?btn('Ask the fact question','interview','','primary'):go('Review related surface drift →','sync','primary')}`);break;}
case 'diagnosis':modal('Review the diagnosis',`<form id="diagnosis-form" data-choice="${id}"><label for="reason">${id==='Accepted'?'What makes this useful?':'Your reason or corrected explanation'}</label><textarea id="reason" required minlength="5" placeholder="Explain your judgment for the audit trail."></textarea><div class="row"><button class="button primary" type="submit">${id==='Accepted'?'Accept':id==='Corrected'?'Save correction':'Dismiss'}</button></div></form>`);break;
case 'interview':modal('Does your after-hours line cover P2 tickets?',`<p>The approved source only covers P1 incidents. Capture the expert’s wording and a source reference; it will remain proposed.</p><form id="interview-form"><label for="expert-answer">Expert answer and source</label><textarea id="expert-answer" required minlength="10">${esc(state.interview)}</textarea><div class="row"><button type="submit" class="button primary">Save proposed answer</button></div></form>`);break;
case 'fact-detail':{const names=['Service area','Support hours','P1 commitment','Pricing band','Contact phone','Booking destination'];modal(`${names[Number(id)]} · source & uses`,`<p>Source: ${Number(id)===1?'Support schedule, version '+state.factVersion:'Northstar example service register, approved 7 Sep 2026'}.</p><div class="note">“${esc([ 'Our coverage area is the Denver–Boulder metro.',state.hours,'After-hours P1 support is governed by the client service agreement.','$125–$185 per user / month, 25-user minimum; onboarding quoted separately; 12-month term.','Our contact phone is +1 (303) 555-0142.','Our booking destination is https://northstar.example/book.'][Number(id)])}”</div><p>Mapped uses: service page, fact page, profile fields and prepared channel copy. Sent email is a historical record and cannot be silently edited.</p><p>Pricing status: ${state.pricing}. Review date: 7 Oct 2026. No actual company document has been uploaded.</p>`);break;}
case 'hours':modal('Change support hours',`<form id="hours-form"><label for="new-hours">New approved support hours</label><input id="new-hours" required minlength="5" value="7 am–9 pm, Monday–Saturday"><div class="note">Review the dependent assets before confirming. Approvals on unpublished page drafts will be invalidated.</div><div class="row"><button class="button primary" type="submit">Review affected assets →</button></div></form>`);break;
case 'confirm-hours':{const value=$('#pending-hours').value;state.hours=value;state.factVersion++;state.approvals={};state.resolved=state.resolved.filter(x=>x!=='hours');state.guided=state.guided.filter(x=>x!=='hours');log('Support hours superseded; draft approvals invalidated; dependent repairs queued');finish();toast('New fact approved. Preview forms updated; external repairs remain queued.');break;}
case 'pricing':modal('Review the proposed pricing band','<div class="copy">$125–$185 per user per month<br>25-user minimum<br>Onboarding quoted separately<br>12-month initial term</div><p>Fictional commercial schedule. Approval adds this band to all fact previews; decline records the choice and keeps it unpublished.</p><div class="row">'+btn('Approve example pricing','pricing-choice','approved','primary')+btn('Decline publication','pricing-choice','declined')+'</div>');break;
case 'pricing-choice':state.pricing=id;state.factVersion++;state.approvals={};log(`Pricing band ${id}; fact previews regenerated`);finish();break;
case 'drift':driftDialog(id);break;
case 'guided':if(!state.guided.includes(id))state.guided.push(id);log('Guided step completed for '+drifts.find(d=>d.id===id).surface+'; re-check pending');finish();toast('Guided step recorded. Re-check before closing the drift.');break;
case 'resolve':if(id==='hours'&&(state.paused||!state.connections['Google Business Profile']))return toast(state.paused?'Publishing is paused.':'Connect demo Google Business Profile first.');if(id!=='hours'&&!state.guided.includes(id))return toast('Complete the guided step first.');if(!isResolved(id)){state.resolved.push(id);log('Sample correction verified: '+drifts.find(d=>d.id===id).surface)}finish();toast('Sample re-check passed. Engine answers have not been refreshed.');break;
case 'source-gap':{const q=questions[Number(id)];modal('Source map: '+q[6],`<p>Question: <b>${q[1]}</b></p><p>Engine: ${q[2]}. Named competitor: ${q[5]}.</p><div class="copy">${q[6].includes('Reddit')?'Suggested response outline: disclose your affiliation, answer the transition question with useful specifics and avoid unsupported comparisons. A person reviews and posts.':'Guided action: review this source’s Northstar entry against the approved contact, coverage and support facts. Submit a factual correction through the source’s own process.'}</div><p>Fictional source observation; no live page was fetched or contacted.</p>${btn(state.bookmarked.includes(Number(id))?'Already saved':'Save guided action','save-gap',id,'primary')}`);break;}
case 'save-gap':if(!state.bookmarked.includes(Number(id)))state.bookmarked.push(Number(id));finish();toast('Guided action saved for human review.');break;
case 'panel':modal('Keep comparisons on the same question panel',`<p>Current panel: version ${state.panel}. Questions, engine settings and market are frozen for comparison.</p><div class="note warn">Starting a new version breaks direct comparison with the old panel. The existing rows remain sample fixtures.</div>${btn('Create new sample panel version','new-panel','','primary')}`);break;
case 'new-panel':state.panel++;log('Question panel version '+state.panel+' created; comparison baseline reset');finish();break;
case 'priority':modal('How the plan is ranked','<p>Relevance 35% + demand 25% + fixable gap 25% + ease 15%, multiplied by data confidence.</p><p>92, 86 and 79 are example scores. Reader access, approved claims and destination permissions remain eligibility gates regardless of score.</p>');break;
case 'save-draft':save();toast('Draft saved in this browser.');break;
case 'approve-draft':{const p=plans.find(x=>x.id===id);if(draftText(p).trim().length<80)return toast('Add meaningful page copy before approval.');if(id==='pricing'&&state.pricing!=='approved')return modal('The pricing claim needs owner approval','<p>Approve the proposed band in Company facts before approving this draft.</p>'+go('Review company facts →','facts','primary'));if(state.published.includes(id))return;if(state.approvals[id]){modal('Simulate publishing this exact version?',`<p>One monthly page slot is reserved for <b>${esc(p.path)}</b>. A successful sample read-back consumes it once.</p><p>No real page will change.</p><div class="row">${btn('Publish & verify in demo','publish',id,'primary')}${btn('Simulate version conflict','conflict',id)}</div>`)}else{state.approvals[id]={text:draftText(p),factVersion:state.factVersion};log('Exact page draft approved: '+p.path);render();toast('Draft approved. The next step simulates publication.')}break;}
case 'publish':{if(state.paused)return toast('Publishing is paused in Controls.');if(!state.connections['WordPress plugin'])return toast('Connect the demo WordPress plugin first.');if(state.blocked||state.probePending)return toast('Resolve and verify reader access before publishing content.');const p=plans.find(x=>x.id===id),approval=state.approvals[id];if(!approval||approval.text!==draftText(p)||approval.factVersion!==state.factVersion)return toast('Draft or facts changed. Approve the current version.');if(!state.published.includes(id)){if(state.published.length>=3)return toast('Monthly allowance reached.');state.published.push(id);state.drafts[id]=approval.text;log('Demo publication verified: '+p.path)}finish();toast('Simulated verification complete. One page slot consumed.');break;}
case 'conflict':delete state.approvals[id];log('Simulated destination conflict: publication blocked, no slot consumed');finish();toast('Conflict detected. Draft retained; review required. No page overwritten.');break;
case 'host-block':state.blocked=true;state.probePending=false;log('Sample Claude host block detected: HTTP 429');render();break;
case 'host-fixed':state.blocked=false;state.probePending=true;log('Host fix reported; probe passes; observed read pending');render();break;
case 'observed':state.probePending=false;log('Sample observed Claude read confirmed; access is 5 of 5');render();break;
case 'access-diff':modal('Review AI access settings',`<p>Proposed policy v2. Only designated reader preferences are in scope; search access remains allowed.</p><pre class="code">UNCHANGED  Search engines: Allow\nPROPOSED   Answer readers: ${esc(state.answerReaders)}\nPROPOSED   Training crawlers: ${esc(state.training)}\nUNCHANGED  Unknown automation: Rate-limit\n\n${state.training==='Limit'?'+ User-agent: GPTBot\n+ Disallow: /\n+ User-agent: ClaudeBot\n+ Disallow: /':'Training preference: allow documented training readers'}\n\nIllustrative excerpt — not a complete robots configuration.</pre><p>Preferences do not override a host block or prove readers will comply. No robots file or Content Signal is written by the demo.</p>${btn('Approve sample policy','approve-access','','primary')}`);break;
case 'approve-access':if(state.paused)return toast('Publishing is paused in Controls.');state.accessApproved=true;log('AI access policy approved in demo; no external settings written');finish();break;
case 'host-email':modal('Host support request — draft only','<div class="copy">Subject: Please check access for Claude’s documented answer reader\n\nOur sample checks show HTTP 429 on home, services, pricing, contact and facts pages. Please review whether a platform-level rule is throttling the reader. Preserve normal security controls and confirm the specific rule and fix. We will re-check both a probe and an observed read afterward.\n\nWebsite: northstar.example</div><div class="note">Preview only. Nothing has been sent. Replace the fictional observations with verified logs in a real request.</div>');break;
case 'wordfence':modal('Review reader access with your site administrator','<ol><li>Check the example 429 against real access logs and the actual rate-limit rule.</li><li>Verify the reader’s documented identity before making a narrowly scoped exception.</li><li>Repeat the page checks and confirm an observed read before marking access healthy.</li></ol><p>This demo does not change plugin rules or verify current vendor settings.</p>');break;
case 'fact-tab':tab=id;render();break;
case 'download-facts':download('northstar-sample-facts.json',JSON.stringify(factData(),null,2),'application/json');toast('Sample facts downloaded.');break;
case 'enquiry-form':modal('Try a fictional enquiry',`<form id="enquiry-demo-form"><label for="enquiry-need">What would you like to discuss?</label><select id="enquiry-need"><option>Managed IT support</option><option>Switching provider</option><option>Pricing and scope</option></select><label for="enquiry-source">How did you hear about us?</label><select id="enquiry-source">${['ChatGPT','Gemini or Google AI','Perplexity','Copilot','Search','Referral','Other'].map(n=>`<option>${n}</option>`).join('')}</select><label for="enquiry-referrer">Observed referral (sample)</label><select id="enquiry-referrer"><option>None</option><option>ChatGPT</option><option>Gemini</option></select><div class="note">No personal data is collected. Submitting shows the source payload; it does not send an enquiry or update the baseline counts.</div><button class="button primary" type="submit">Preview source payload</button></form>`);break;
case 'download-report':download('New-Answority-Owner-Report.txt',reportText());toast('Sample Owner Report downloaded.');break;
case 'receipt':{const p=plans.find(x=>x.id===id);modal('Publication receipt',p?`<p><b>${p.path}</b></p><div class="steps"><span>Approved</span><span>Sample published</span><span>Sample verified</span></div><div class="copy">${esc(state.drafts[id]??p.text())}</div><div class="note">No live URL changed. Outcome: not measured. Current fact version ${state.factVersion}; later fact changes require a new repair review.</div>`:'<p>Seeded managed services overview · 8 Sep 2026. Represents one historical verified update in the sample. No actual external publication occurred.</p>');break;}
case 'connection':state.connections[id]=!state.connections[id];save();render();toast(id+(state.connections[id]?' connected':' disconnected')+' in demo.');break;
case 'pause':state.paused=!state.paused;save();render();toast(state.paused?'Simulated publishing paused.':'Simulated publishing resumed.');break;
case 'reset':modal('Reset Answority Dashboard?','<p>Clear v3 draft edits, approvals and simulated actions in this browser. The original demo has separate storage.</p>'+btn('Reset v3 demo','confirm-reset','','danger'));break;
case 'confirm-reset':state=fresh();save();$('#dialog').close();location.hash='overview';render();toast('Answority Dashboard reset.');break;
}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='diagnosis-form'){state.diagnosis=form.dataset.choice;state.diagnosisReason=$('#reason').value.trim();log('Diagnosis '+state.diagnosis.toLowerCase());finish()}if(form.id==='interview-form'){state.interview=$('#expert-answer').value.trim();log('Expert answer saved as proposed; approval still required');finish();toast('Proposed fact captured. It cannot yet support published claims.')}if(form.id==='hours-form'){const value=$('#new-hours').value.trim();modal('Review affected assets',`<input type="hidden" id="pending-hours" value="${esc(value)}"><p>Approve: <strong>${esc(value)}</strong></p>${table(['Dependent asset','After approval'],[['Service page','Repair proposal; review before publication'],['Fact-page previews','All four regenerate from the new claim'],['Google Business Profile','Correction queued for approval'],['Bing Places','Guided update'],['Clutch','Guided update'],['LinkedIn post','Edit draft; app access or export'],['Email sent 2 Aug','Historical — correction offered, original retained']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`))}<div class="note">Existing unapproved draft text is retained, but its approval is cleared. Inspect and update the text before approving again.</div>${btn('Approve new fact version','confirm-hours','','primary')}`)}if(form.id==='enquiry-demo-form'){const source=$('#enquiry-source').value,referrer=$('#enquiry-referrer').value;const cls=['ChatGPT','Gemini or Google AI','Perplexity','Copilot'].includes(source)?'buyer-reported assistant':referrer!=='None'?'AI-referred':source==='Referral'?'referral':source==='Other'?'other / unknown':'direct / search';modal('Enquiry source payload — preview',`<pre class="code">${esc(JSON.stringify({sourceClass:cls,buyerReportedSource:source,observedReferrer:referrer,request:$('#enquiry-need').value,landingPage:'/managed-it-services',identity:'human or unverified',crmDelivery:'not sent — demo only'},null,2))}</pre><p>Both the buyer answer and the observed referral are preserved. A reader identity is not inferred from an assistant selection.</p>`)}if(form.id==='audit-form'){state.auditRun=true;save();render();toast('Sample audit ready. No domain was scanned.')}});
document.addEventListener('input',event=>{if(event.target.id==='draft'){const id=event.target.dataset.id;state.drafts[id]=event.target.value;delete state.approvals[id];save();const control=$('[data-action="approve-draft"]');if(control)control.textContent='Approve exact draft'}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='engine-filter'){answerFilter=el.value;render()}if(el.id==='intent-filter'){questionFilter=el.value;render()}if(el.id==='visitor-period'){visitorPeriod=el.value;render()}if(el.id==='training-policy'||el.id==='answer-policy'){state[el.id==='training-policy'?'training':'answerReaders']=el.value;state.accessApproved=false;save();render()}if(el.dataset.lead!==undefined){state.leads[Number(el.dataset.lead)]=el.value;save();toast('Qualification saved. Overview count updated.')}});
window.addEventListener('hashchange',()=>{$('#dialog').close();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});render();
